messages.content:
Write a single self-contained HTML file with a 3D animation using three.js. three.js r160 is available as an ES module at './three.module.js' -- import it with:
  import * as THREE from './three.module.js';
Scene: a low-poly 3D humanoid figure performs this exact cycle on a treadmill-style ground, side-on camera: stands still for 2 seconds, walks in place for 3 seconds (limbs swinging at walking pace), runs in place for 3 seconds (faster, larger limb swings, slight forward lean), then stands still again for 2 seconds. The 10-second cycle loops forever and must start immediately on load. Limb movement must clearly differ between walking and running. No external assets besides the three.js import. Output ONLY the HTML in one code block.

response.text:
```html
<!DOCTYPE html>
<html>
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Low-poly Humanoid Treadmill Cycle</title>
    <style>
        body { margin: 0; overflow: hidden; background-color: #1a1a2e; font-family: Arial, Helvetica, sans-serif; }
        canvas { display: block; }
        .info {
            position: absolute;
            bottom: 20px;
            left: 20px;
            color: #aaa;
            font-size: 14px;
            background: rgba(0,0,0,0.5);
            padding: 6px 12px;
            border-radius: 6px;
            pointer-events: none;
            z-index: 10;
        }
    </style>
</head>
<body>
    <div class="info">Stand 2s → Walk 3s → Run 3s → Stand 2s</div>

    <script type="importmap">
        {
            "imports": {
                "three": "./three.module.js"
            }
        }
    </script>

    <script type="module">
        import * as THREE from './three.module.js';

        // --- Setup scene, camera, renderer ---
        const scene = new THREE.Scene();
        scene.background = new THREE.Color(0x1a1a2e);
        scene.fog = new THREE.Fog(0x1a1a2e, 12, 25);

        const camera = new THREE.PerspectiveCamera(50, window.innerWidth / window.innerHeight, 0.1, 100);
        camera.position.set(3.2, 1.6, 5.2);
        camera.lookAt(0, 0.8, 0);

        const renderer = new THREE.WebGLRenderer({ antialias: true });
        renderer.setSize(window.innerWidth, window.innerHeight);
        renderer.shadowMap.enabled = true;
        renderer.shadowMap.type = THREE.PCFSoftShadowMap;
        document.body.appendChild(renderer.domElement);

        // --- Lights ---
        const ambient = new THREE.AmbientLight(0x404060, 1.2);
        scene.add(ambient);

        const dirLight = new THREE.DirectionalLight(0xffeedd, 1.2);
        dirLight.position.set(2, 4, 3);
        dirLight.castShadow = true;
        dirLight.shadow.mapSize.width = 512;
        dirLight.shadow.mapSize.height = 512;
        dirLight.shadow.camera.near = 0.5;
        dirLight.shadow.camera.far = 10;
        dirLight.shadow.camera.left = -2;
        dirLight.shadow.camera.right = 2;
        dirLight.shadow.camera.top = 2;
        dirLight.shadow.camera.bottom = -2;
        scene.add(dirLight);

        const fillLight = new THREE.PointLight(0x4466ff, 0.5);
        fillLight.position.set(-2, 1.5, 2);
        scene.add(fillLight);

        // --- Ground (treadmill-style) ---
        const groundGeo = new THREE.BoxGeometry(4, 0.1, 1.8);
        const groundMat = new THREE.MeshStandardMaterial({ color: 0x3a3a4a, roughness: 0.8 });
        const ground = new THREE.Mesh(groundGeo, groundMat);
        ground.position.y = -0.55;
        ground.receiveShadow = true;
        ground.castShadow = false;
        scene.add(ground);

        // Treadmill side rails
        const railMat = new THREE.MeshStandardMaterial({ color: 0x555566, roughness: 0.6 });
        const leftRail = new THREE.Mesh(new THREE.BoxGeometry(0.15, 0.15, 2.0), railMat);
        leftRail.position.set(-1.9, -0.4, 0);
        leftRail.castShadow = true;
        scene.add(leftRail);
        const rightRail = new THREE.Mesh(new THREE.BoxGeometry(0.15, 0.15, 2.0), railMat);
        rightRail.position.set(1.9, -0.4, 0);
        rightRail.castShadow = true;
        scene.add(rightRail);

        // Belt lines
        const beltMat = new THREE.MeshStandardMaterial({ color: 0x2a2a3a, roughness: 0.9 });
        for (let i = -2; i <= 2; i += 0.5) {
            const line = new THREE.Mesh(new THREE.BoxGeometry(0.02, 0.01, 0.3), beltMat);
            line.position.set(i, -0.48, 0.9);
            scene.add(line);
            const line2 = new THREE.Mesh(new THREE.BoxGeometry(0.02, 0.01, 0.3), beltMat);
            line2.position.set(i, -0.48, -0.9);
            scene.add(line2);
        }

        // --- Build low-poly humanoid (proportions: total ~1.7 units) ---
        const humanoid = new THREE.Group();
        humanoid.position.y = 0;

        // Materials
        const skinMat = new THREE.MeshStandardMaterial({ color: 0x8a6e5a, roughness: 0.7 });
        const shirtMat = new THREE.MeshStandardMaterial({ color: 0x4a6a8a, roughness: 0.6 });
        const pantsMat = new THREE.MeshStandardMaterial({ color: 0x3a4a5a, roughness: 0.7 });
        const shoeMat = new THREE.MeshStandardMaterial({ color: 0x2a2a2a, roughness: 0.8 });

        // Torso
        const torso = new THREE.Mesh(new THREE.BoxGeometry(0.55, 0.7, 0.35), shirtMat);
        torso.position.y = 0.95;
        torso.castShadow = true;
        humanoid.add(torso);

        // Head
        const head = new THREE.Mesh(new THREE.BoxGeometry(0.35, 0.35, 0.35), skinMat);
        head.position.y = 1.45;
        head.castShadow = true;
        humanoid.add(head);

        // Hat / hair
        const hair = new THREE.Mesh(new THREE.BoxGeometry(0.38, 0.12, 0.38), new THREE.MeshStandardMaterial({ color: 0x2a1a1a }));
        hair.position.y = 1.62;
        hair.castShadow = true;
        humanoid.add(hair);

        // Arms (left and right) - groups for rotation
        const leftArmGroup = new THREE.Group();
        leftArmGroup.position.set(-0.35, 1.0, 0);
        const leftUpperArm = new THREE.Mesh(new THREE.BoxGeometry(0.15, 0.5, 0.15), skinMat);
        leftUpperArm.position.y = -0.25;
        leftUpperArm.castShadow = true;
        leftArmGroup.add(leftUpperArm);
        const leftLowerArm = new THREE.Mesh(new THREE.BoxGeometry(0.13, 0.45, 0.13), skinMat);
        leftLowerArm.position.y = -0.7;
        leftLowerArm.castShadow = true;
        leftArmGroup.add(leftLowerArm);
        humanoid.add(leftArmGroup);

        const rightArmGroup = new THREE.Group();
        rightArmGroup.position.set(0.35, 1.0, 0);
        const rightUpperArm = new THREE.Mesh(new THREE.BoxGeometry(0.15, 0.5, 0.15), skinMat);
        rightUpperArm.position.y = -0.25;
        rightUpperArm.castShadow = true;
        rightArmGroup.add(rightUpperArm);
        const rightLowerArm = new THREE.Mesh(new THREE.BoxGeometry(0.13, 0.45, 0.13), skinMat);
        rightLowerArm.position.y = -0.7;
        rightLowerArm.castShadow = true;
        rightArmGroup.add(rightLowerArm);
        humanoid.add(rightArmGroup);

        // Legs (groups)
        const leftLegGroup = new THREE.Group();
        leftLegGroup.position.set(-0.17, 0.55, 0);
        const leftUpperLeg = new THREE.Mesh(new THREE.BoxGeometry(0.18, 0.5, 0.18), pantsMat);
        leftUpperLeg.position.y = -0.25;
        leftUpperLeg.castShadow = true;
        leftLegGroup.add(leftUpperLeg);
        const leftLowerLeg = new THREE.Mesh(new THREE.BoxGeometry(0.15, 0.5, 0.15), pantsMat);
        leftLowerLeg.position.y = -0.75;
        leftLowerLeg.castShadow = true;
        leftLegGroup.add(leftLowerLeg);
        const leftFoot = new THREE.Mesh(new THREE.BoxGeometry(0.17, 0.1, 0.28), shoeMat);
        leftFoot.position.y = -1.0;
        leftFoot.position.z = 0.06;
        leftFoot.castShadow = true;
        leftLegGroup.add(leftFoot);
        humanoid.add(leftLegGroup);

        const rightLegGroup = new THREE.Group();
        rightLegGroup.position.set(0.17, 0.55, 0);
        const rightUpperLeg = new THREE.Mesh(new THREE.BoxGeometry(0.18, 0.5, 0.18), pantsMat);
        rightUpperLeg.position.y = -0.25;
        rightUpperLeg.castShadow = true;
        rightLegGroup.add(rightUpperLeg);
        const rightLowerLeg = new THREE.Mesh(new THREE.BoxGeometry(0.15, 0.5, 0.15), pantsMat);
        rightLowerLeg.position.y = -0.75;
        rightLowerLeg.castShadow = true;
        rightLegGroup.add(rightLowerLeg);
        const rightFoot = new THREE.Mesh(new THREE.BoxGeometry(0.17, 0.1, 0.28), shoeMat);
        rightFoot.position.y = -1.0;
        rightFoot.position.z = 0.06;
        rightFoot.castShadow = true;
        rightLegGroup.add(rightFoot);
        humanoid.add(rightLegGroup);

        // --- Animation timing ---
        // Cycle: 0-2s stand, 2-5s walk, 5-8s run, 8-10s stand
        const CYCLE_DURATION = 10;
        const STAND1_START = 0;
        const STAND1_END = 2;
        const WALK_START = 2;
        const WALK_END = 5;
        const RUN_START = 5;
        const RUN_END = 8;
        const STAND2_START = 8;
        const STAND2_END = 10;

        // --- Animation state ---
        let clock = new THREE.Clock();

        // --- Animation update function ---
        function animate() {
            const delta = clock.getDelta();
            const elapsed = clock.getElapsedTime();
            const t = elapsed % CYCLE_DURATION;

            // Determine phase and compute limb angles
            let walkPhase = 0;
            let runPhase = 0;
            let isWalking = false;
            let isRunning = false;
            let leanAngle = 0; // forward lean for run

            if (t >= STAND1_START && t < STAND1_END) {
                // stand still
                walkPhase = 0;
                runPhase = 0;
                leanAngle = 0;
            } else if (t >= WALK_START && t < WALK_END) {
                isWalking = true;
                const localT = t - WALK_START;
                walkPhase = localT * 2 * Math.PI; // 2 full cycles over 3 seconds -> speed ~ 2π per 1.5s? Actually 3s -> 2 full swings = 4π? Let's do 2 full cycles per 3s => phase speed 2π per 1.5s => localT*2π/1.5? simpler: 2 full cycles in 3s => 2*2π = 4π over 3s => phase = localT * (4π/3)
                walkPhase = localT * (4 * Math.PI / 3);
                leanAngle = 0.05;
            } else if (t >= RUN_START && t < RUN_END) {
                isRunning = true;
                const localT = t - RUN_START;
                runPhase = localT * (8 * Math.PI / 3); // 4 full cycles in 3s => 8π over 3s
                leanAngle = 0.18;
            } else {
                // stand still again
                walkPhase = 0;
                runPhase = 0;
                leanAngle = 0;
            }

            // Compute swing angles
            // Walk: moderate amplitude ~0.6 rad for arms, 0.5 for legs
            // Run: larger amplitude ~1.2 rad arms, 1.0 legs, faster
            let leftArmAngle = 0;
            let rightArmAngle = 0;
            let leftLegAngle = 0;
            let rightLegAngle = 0;

            if (isWalking) {
                leftArmAngle = Math.sin(walkPhase) * 0.65;
                rightArmAngle = Math.sin(walkPhase + Math.PI) * 0.65;
                leftLegAngle = Math.sin(walkPhase + Math.PI) * 0.55;
                rightLegAngle = Math.sin(walkPhase) * 0.55;
            } else if (isRunning) {
                leftArmAngle = Math.sin(runPhase) * 1.25;
                rightArmAngle = Math.sin(runPhase + Math.PI) * 1.25;
                leftLegAngle = Math.sin(runPhase + Math.PI) * 1.1;
                rightLegAngle = Math.sin(runPhase) * 1.1;
            } else {
                // stand: all zero
            }

            // Apply rotations (in radians)
            // Arms: rotate around Z (forward-back) - using Z axis for side view? Actually side view camera at +Z looking at -Z? Camera at (3.2,1.6,5.2) looking at origin, so Z is depth. For side-on, we want limbs swinging in Z (forward/back) plane. Rotate around X axis for forward-back swing? Wait side view means we see XZ plane? Actually camera is at +Z looking at origin, so we see X (horizontal) and Y (vertical) but Z is depth. For walking in place, limbs swing forward/backward along Z. So rotation around X axis (pitch) gives forward/back swing. Yes, rotate around X.
            leftArmGroup.rotation.x = leftArmAngle;
            rightArmGroup.rotation.x = rightArmAngle;
            leftLegGroup.rotation.x = leftLegAngle;
            rightLegGroup.rotation.x = rightLegAngle;

            // Forward lean for running (rotate whole humanoid around X? Actually lean forward means rotate around X? If camera is side view, forward is +Z? Wait camera looks from +Z to origin, so forward is -Z? Actually humanoid faces +Z? We need to define facing direction. For side-on camera, we want humanoid facing along Z (towards camera? or away?). Let's set humanoid facing +Z (towards camera). Then forward lean is rotating around X (pitch) by negative? Let's set lean as rotation around X: positive rotates top toward +Z? In three, rotation.x positive rotates Y toward Z? Actually rotation.x positive rotates Y toward Z (for right-hand coordinate). So to lean forward (towards +Z), we rotate around X by negative? Let's test: If we rotate humanoid.rotation.x = -leanAngle, the top leans towards +Z? Actually for a positive rotation around X, the Y axis rotates toward Z (counterclockwise looking from +X). So positive rotation.x tilts the head towards -Z? Let's just set humanoid.rotation.x = -leanAngle to lean forward (+Z). Since camera is at +Z, leaning forward means leaning towards camera. That's fine.
            humanoid.rotation.x = -leanAngle;

            // Also add slight bob for running
            if (isRunning) {
                humanoid.position.y = Math.sin(runPhase * 2) * 0.04;
            } else if (isWalking) {
                humanoid.position.y = Math.sin(walkPhase * 2) * 0.02;
            } else {
                humanoid.position.y = 0;
            }

            // Render
            renderer.render(scene, camera);
            requestAnimationFrame(animate);
        }

        // Start animation immediately
        animate();

        // Handle resize
        window.addEventListener('resize', () => {
            camera.aspect = window.innerWidth / window.innerHeight;
            camera.updateProjectionMatrix();
            renderer.setSize(window.innerWidth, window.innerHeight);
        });
    </script>
</body>
</html>
```
